import{_ as p,o as a,c as r,a2 as o}from"./chunks/framework.DnrXFDHb.js";const P=JSON.parse('{"title":"上架率65%是生死线：三个KPI联动决定智算中心盈亏","description":"","frontmatter":{"title":"上架率65%是生死线：三个KPI联动决定智算中心盈亏","updated":"2026-08-25T00:00:00.000Z","visibility":"public"},"headers":[],"relativePath":"智算中心投建运/上架率65是生死线_三个KPI联动决定智算中心盈亏.md","filePath":"智算中心投建运/上架率65是生死线_三个KPI联动决定智算中心盈亏.md","lastUpdated":null}'),n={name:"智算中心投建运/上架率65是生死线_三个KPI联动决定智算中心盈亏.md"};function e(s,t,i,_,l,g){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="上架率65-是生死线-三个kpi如何联动决定智算中心盈亏" tabindex="-1">上架率65%是生死线：三个KPI如何联动决定智算中心盈亏 <a class="header-anchor" href="#上架率65-是生死线-三个kpi如何联动决定智算中心盈亏" aria-label="Permalink to &quot;上架率65%是生死线：三个KPI如何联动决定智算中心盈亏&quot;">​</a></h1><blockquote><p><strong>公众号摘要</strong>（发布时填入摘要栏，不进入正文）：65% 不是拍脑袋——政策目标、评级机构测算、一线实战三个口径都指向 60%–75% 这个区间。但真正决定生死的不是上架率本身，而是它和点亮率、PUE 的乘法关系。这篇文章把联动测算模型拆开给你，看完自己就能算。</p></blockquote><p>【封面图建议，发布时替换为实际图片】深色机房机柜阵列，前景压一个发红光的「65%」，三条亮线从「上架率 / 点亮率 / PUE」汇聚到中间一台天平，底部压主标题。</p><hr><p>先说句掏心窝的：我干了 20 年地产，管过基金、做过经营性物业的募投管退，最近几年又扎进电力交易和 HVDC 供电架构。现在开这个号，就是想用「资产 + 电力」的双重视角，把算电协同这件事讲清楚。本文由 AI 帮我整理资料和初稿，但每一个判断——比如为什么我说「今年的点亮率，是明年的上架率」——都是我自己的体感。AI 没去过项目现场，我没让它替我做判断。也欢迎你在评论区拍砖——这个号不是我一个人的学习笔记，是咱们一起研习的地方。</p><p>朋友最近拿一份智算中心的可研报告来问我。两百页，前面全是 GPU 集群配置、网络拓扑、液冷方案，技术感拉满。</p><p>我翻了半天，问他：上架率你们按多少做的？PUE 取的是设计值还是实测值？点亮率有没有单独假设？</p><p>他愣了一下：这三个数，报告里还真没细写。</p><p>我说，那你这份可研，前面两百页写得再好，也可能是一栋盖好了却租不出去的商场。</p><h3 id="_65-不是行规-是三个口径凑出来的" tabindex="-1">65% 不是行规，是三个口径凑出来的 <a class="header-anchor" href="#_65-不是行规-是三个口径凑出来的" aria-label="Permalink to &quot;65% 不是行规，是三个口径凑出来的&quot;">​</a></h3><p>先把丑话说前面：<strong>65% 不是谁的官方标准，是三个独立口径交叉出来的区间中值。</strong></p><p>政策口径：工信部 2021 年《新型数据中心发展三年行动计划》提出，全国数据中心平均利用率力争提升到 60% 以上；联合资信 2026 年的研报也把「2025 年底全国数据中心整体上架率不低于 60%」列为政策硬指标。60%，是政策给行业画的及格线。</p><p>测算口径：联合资信那份研报（2026.02）按典型 IDC 项目做盈亏平衡测算，基础假设下的保本上架率是 <strong>62.46%</strong>——这是评级机构口径里少有的精确值。</p><p>实战口径：软通动力首席人工智能官金亚东说得更狠——智算中心上架率不足 70%–75%，根本没办法盈利（雷峰网，2025.04）。</p><p>政策说 60%，评级机构算出来 62.46%，一线玩家说要 70%–75%。<strong>三个口径落在 60%–75% 的区间里，取 65% 当「典型项目的生死线」，是区间中间偏保守的位置。</strong> 做过购物中心的都懂——这就是出租率生死线，只不过分母里多了一项跟着出租率一起涨的电费。</p><h3 id="生死线会漂-谁在给这条线挪位置" tabindex="-1">生死线会漂：谁在给这条线挪位置 <a class="header-anchor" href="#生死线会漂-谁在给这条线挪位置" aria-label="Permalink to &quot;生死线会漂：谁在给这条线挪位置&quot;">​</a></h3><p>65% 不是钉死的。我自己建了个简版模型，你把自己的参数代进去就能用：</p><p>假设一个批发型智算中心，IT 负荷 10MW，机电加土建 CapEx 6 个亿（不含服务器），折旧 10 年，年固定成本约 8200 万；PUE 1.25（970 号文红线：2025 年底新建大型、超大型数据中心 ≤1.25，国家枢纽节点 ≤1.2）；综合电价 0.68 元/度，上架后负载率 65%，租金每 kW·月 1450 元【均为假设口径】。</p><p><strong>生死线上架率 = 年固定成本 ÷（满租年收入 − 满载年电费）</strong> = 8200 万 ÷（1.74 亿 − 4840 万）≈ 65%。</p><p>然后看四只手怎么推这条线。我的模型算出来：租金降 10%，生死线抬到 76%；PUE 从 1.25 恶化到 1.4，移到 68%；电价涨到 0.80 元/度，移到 70%。</p><p>联合资信用自己的假设独立测算，方向一致、幅度更吓人：<strong>租金跌 10%，保本上架率飙到 100%；折旧缩短到 10 年，飙到 84.28%。</strong> 两套独立模型指向同一结论——<strong>租金是弹性最大的变量，PUE×电价联动定成本，折旧是沉默的定时炸弹。</strong></p><p>所以我说 PUE 就是数据中心的「公摊系数」：PUE 1.25，相当于每用 100 度 IT 的电，就要为「公摊面积」多付 25 度，公摊越高生死线越高。以前做地产，电费是物业费，羊毛出在租户身上；现在看智算中心，电费是房贷，直接决定这笔资产还不起月供。</p><h3 id="上架-挣钱-中间隔着一道「点亮率」" tabindex="-1">上架 ≠ 挣钱，中间隔着一道「点亮率」 <a class="header-anchor" href="#上架-挣钱-中间隔着一道「点亮率」" aria-label="Permalink to &quot;上架 ≠ 挣钱，中间隔着一道「点亮率」&quot;">​</a></h3><p>大多数人看智算中心，看到上架率就停了。这是第一个坑。</p><p>行业里有两把关键的尺子：上架率看设备有没有装上架、通电可运行；点亮率看设备有没有真的在跑计算任务（雷峰网，2025.04）。再细的口径还有 MFU——摩尔线程 2025 年年报披露，万卡集群有效训练时间占比超 90%，但 MoE 训练的 MFU 只有 40%。<strong>「一直在跑」和「跑出多少有效算力」，是两回事。</strong></p><p>真实世界的点亮率有多低？金亚东的说法是 20%，「实际情况可能比这更糟糕」；中国信通院的报告显示，传统模式下智算中心 GPU 平均利用率低于 30%（虎嗅转引，2026.08）。</p><p>翻译成人话：一个上架率 65% 的智算中心，如果点亮率只有 30%，真正在烧电出算力的设备是 65% × 30% ≈ <strong>不到两成</strong>。铺子租出去了，但一半的店没开业，开业的一半没客人。</p><h3 id="点亮率怎么杀人-两种计费模式-两种死法" tabindex="-1">点亮率怎么杀人：两种计费模式，两种死法 <a class="header-anchor" href="#点亮率怎么杀人-两种计费模式-两种死法" aria-label="Permalink to &quot;点亮率怎么杀人：两种计费模式，两种死法&quot;">​</a></h3><p>点亮率不在盈亏公式里直接出现，但它杀项目的方式有两种——这也是很多分析没讲透的地方。</p><p><strong>第一种，按算力计费模式：乘法国刑。</strong> 客户按卡时、按 Token 付钱，收入 ≈ 上架率 × 点亮率 × 单价。设备上架即按额定功率耗电（电费跟上架率走），收入却跟点亮率走，那么实际保本上架率 ≈ 名义保本线 ÷ 点亮率：点亮率 90%，保本线 72%；60%，变成 108%——租满都保不了本；30%，这条线物理上不存在【简化模型，仅展示联动方向】。这两年大量按算力计费的智算中心亏损，数学解释就在这里：<strong>不是算力不先进，是点亮率这个分母把整栋楼的账算死了。</strong></p><p><strong>第二种，包机柜模式：慢性毒药。</strong> 租金按机柜照收，客户空转你一分钱不少——甚至因为电费省了，当期报表更好看。我的模型里，负载率从 65% 降到 55%，生死线反而降到 62%。看出扭曲了吗？<strong>包机柜模式下，客户算力空转对运营商反而是「利好」。</strong> 但客户花同样的租金，点亮率 30% 和 60% 拿到的有效算力差一倍——点亮率就是客户侧的投资回报率。它长期低迷，客户要么不续租砸上架率，要么逼你降价砸租金，而这两个恰是移动生死线最狠的变量。</p><p>所以传导链是：PUE × 电价定成本斜率，上架率定当期收入，<strong>点亮率决定 6 到 18 个月后的上架率和租金</strong>——它是先行指标，上架率是滞后指标。等你从上架率看到问题，窟窿早在一年前的点亮率里挖好了。<strong>今年的点亮率，就是明年的上架率。</strong></p><p>有没有绕开点亮率的模式？有，批发型长租——把整层机柜租给一个大客户，签按满载计费的条款，空转租金照收。这就像购物中心把整层楼租给主力店：店里有没有客人，租金按月到账。代价是把空置风险让渡给了客户，自己也让出了议价权和租金弹性。零售型散租的玩家没这个护身符，只能在点亮率的乘法国刑里硬扛。</p><h3 id="拿这套模型照一照行业现状" tabindex="-1">拿这套模型照一照行业现状 <a class="header-anchor" href="#拿这套模型照一照行业现状" aria-label="Permalink to &quot;拿这套模型照一照行业现状&quot;">​</a></h3><p>《科技日报》报道过一个典型案例：西部某城千卡规模智算中心，上架率不足 50%，已上架服务器实际利用率不到 30%，一年运营成本超过 3000 万元（观察者网转引，2026.07）。按上面的乘法算，它的有效产出不到两成——这不是「没救」，是「正在流血而不自知」。</p><p>需求端还在压价：36氪报道，一台 H100 八卡服务器月租从 2024 年初的 12–18 万元跌到当年底 7.5 万元，一年腰斩（2024.12，上一代旗舰卡口径）。租金往下走，生死线往上蹿；点亮率起不来，收入端再乘一刀——三面夹击。</p><p>也不是全军覆没：工信部公布的全国算力设施整体上架率 71.4%，重庆人工智能创新中心公共算力使用率超 85%（虎嗅，2026.08）——平均值掩盖的是分化，有客户、有点亮率的节点活得很好。</p><p>干了 20 年地产，我见过写字楼空置潮——空置率上三成，业主降价、改造、认亏离场，三部曲。现在的智算中心在重演这一轮，只是节奏快得多。说句重话：<strong>智算中心首先是门收租生意，然后才是科技生意。</strong> 顺序搞反了，再贵的 GPU 也只是落灰的固定资产。</p><h3 id="给看项目的人三个检查动作" tabindex="-1">给看项目的人三个检查动作 <a class="header-anchor" href="#给看项目的人三个检查动作" aria-label="Permalink to &quot;给看项目的人三个检查动作&quot;">​</a></h3><p>如果你正在评估一个智算中心项目，别先问「用什么卡」，先问三个数：</p><p><strong>第一，问租约结构。</strong> 批发还是零售？有没有大客户长租锁定、有没有按满载计费的条款？这决定上架率的含金量。</p><p><strong>第二，问 PUE 是设计值还是实测值。</strong> 设计 1.2 的机房实际跑出 1.35 很常见——用实测值重算生死线，结论可能整个翻面。</p><p><strong>第三，问点亮率，而不是只问上架率。</strong> 按算力计费的项目，上架率除以点亮率再说话；包机柜的项目，问客户续租率和租金谈判记录——那是点亮率的滞后回声。</p><p>这三问，问得倒市面上至少一半的可研报告。</p><p>最后泼两盆冷水。第一盆：65% 是测算值不是及格线，你的 CapEx、电价、租金不同，生死线可能 55% 也可能 75%，照抄别人的线比没有线更危险。第二盆：口径之乱还要持续，上架率、点亮率、GPU 利用率、MFU 混着报是常态，融资材料挑好看的口径写是人性——多问一句「这是哪把尺子量出来的」，能避开一半的坑。</p><p>问题留给大家：<strong>你手上项目的三个数——上架率、点亮率、PUE——分别是多少？代进模型，你的生死线落在哪？</strong> 欢迎在评论区报数，咱们一起把这张生死线地图画得更准。一个人捋容易钻牛角尖，一群人捋才能捋透。</p><hr><p>数据来源： [1] 联合资信《投资加速背景下，基于盈亏平衡框架的 IDC 企业信用特征研究》（2026.02）｜保本上架率 62.46% 及租金/折旧/PUE 敏感性 [2] 雷峰网《互联网大厂「算力荒」，智算中心却在「卖卡」求生》（2025.04）｜上架率/点亮率口径、金亚东访谈 [3] 虎嗅《中国算力短缺未结束，已从「有没有」分化为「边缺边闲」》（2026.08）｜工信部上架率 71.4%、信通院 GPU 利用率口径、重庆/湖南案例、摩尔线程 MFU [4] 观察者网（转引科技日报，2026.07）｜西部千卡智算中心低利用率案例 [5] 36氪《花几个亿建智算中心，八成的 GPU 租不出去》（2024.12）｜H100 租赁价格走势（2024 年口径）</p><p>⚠️ 风险提示：文中 65% 为三个公开口径交叉的区间中值与模型测算值，非行业标准；实际盈亏平衡随租金、电价、PUE、折旧年限、计费模式大幅漂移，请勿直接套用。本文仅作产业研究，不构成任何投资建议。</p><p>关注「算电协同研习社」，也欢迎在评论区拍砖——一个人捋容易钻牛角尖，一群人捋才能捋透。</p>',50)])])}const d=p(n,[["render",e]]);export{P as __pageData,d as default};
